// Product interactions adapted from TempVault's FolderLibrary and preview motion.
const folderTypes={pdf:{label:'PDFs',description:'PDF documents',color:'#ef4444'},doc:{label:'Word & text',description:'Documents and notes',color:'#3b82f6'},img:{label:'Images',description:'Pictures and graphics',color:'#a855f7'},zip:{label:'Archives',description:'Compressed packages',color:'#f59e0b'}};
const folderSvg='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h6l2 2h10v11H3z"/></svg>';
let openFolder=null;
function folderCard(type,context){const info=folderTypes[type],items=files.filter(f=>f.type===type),open=context==='library'&&openFolder===type;return `<article class="glass-folder-card ${open?'open':''}" style="--folder-color:${info.color}" data-folder-card="${type}"><button class="folder-cover" data-folder-toggle="${type}" data-context="${context}" aria-expanded="${open}" aria-label="${info.label} folder"><span class="folder-tab"></span><span class="folder-sheets" aria-hidden="true">${[0,1,2].map(i=>`<i style="--sheet-index:${i}">${icon({type})}</i>`).join('')}</span><span class="folder-glass"><span>${folderSvg}</span><strong>${info.label}</strong><small>${info.description}</small><b>${items.length} FILE${items.length===1?'':'S'}</b></span></button>${context==='library'?`<div class="folder-files-reveal" ${open?'':'inert'}><div class="folder-files">${items.map(f=>`<div class="file-row" data-file="${f.id}" tabindex="0" role="button" aria-label="Preview ${f.name}">${icon(f)}<div class="file-info"><strong>${f.name}</strong><small>${f.label} · ${f.size}</small></div></div>`).join('')}</div></div>`:''}</article>`}
function bindFolders(root){root.querySelectorAll('.folder-cover').forEach(cover=>{cover.onpointermove=e=>{if(reduceMotion.matches)return;const r=cover.getBoundingClientRect();cover.style.setProperty('--folder-rx',`${((e.clientY-r.top)/r.height-.5)*-5}deg`);cover.style.setProperty('--folder-ry',`${((e.clientX-r.left)/r.width-.5)*7}deg`)};cover.onpointerleave=()=>{cover.style.removeProperty('--folder-rx');cover.style.removeProperty('--folder-ry')};cover.onclick=()=>{const type=cover.dataset.folderToggle;if(cover.dataset.context==='library'){openFolder=openFolder===type?null:type;root.querySelectorAll('[data-folder-card]').forEach(card=>{const open=card.dataset.folderCard===openFolder;card.classList.toggle('open',open);card.querySelector('.folder-cover').setAttribute('aria-expanded',open);card.querySelector('.folder-files-reveal').inert=!open})}else{root.querySelectorAll('.glass-folder-card').forEach(card=>{const open=card.dataset.folderCard===type;card.classList.toggle('open',open);card.querySelector('button').setAttribute('aria-expanded',open)});const f=files.find(f=>f.type===type);$('#folder-detail').textContent=`↳ ${f.name} · ${f.label} · ${f.size}`}}})}
const baseRender=render;
render=function(){baseRender();if(view==='folders'){$('#file-list').innerHTML='<div class="folder-card-grid">'+Object.keys(folderTypes).map(type=>folderCard(type,'library')).join('')+'</div>';bindFolders($('#file-list'));$$('#file-list [data-file]').forEach(row=>{row.onclick=()=>openDemoFile(+row.dataset.file);row.onkeydown=e=>{if(e.target===row&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openDemoFile(+row.dataset.file)}}})}$$('#file-list [data-file]').forEach(row=>{row.insertAdjacentHTML('afterbegin',`<button class="file-grab" aria-label="Drag ${files.find(f=>f.id===+row.dataset.file).name} to preview">⠿</button>`);row.querySelector('.file-grab').onclick=e=>{e.stopPropagation();openDemoFile(+row.dataset.file)};row.querySelector('.file-grab').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.stopPropagation();openDemoFile(+row.dataset.file)}}})};
function openDemoFile(id){selected=id;if(!previews.includes(id))previews.push(id);switchTab('preview');render();renderPreviews()}
$('.folder-options').innerHTML=['pdf','doc','img'].map(type=>folderCard(type,'feature')).join('');bindFolders($('.folder-options'));
const basePreviews=renderPreviews;
renderPreviews=function(){const existing=new Set($$('[data-card]').map(c=>c.dataset.card));basePreviews();if(!reduceMotion.matches)$$('[data-card]').filter(c=>!existing.has(c.dataset.card)).forEach(c=>c.animate([{opacity:0,transform:'translateY(-12px) scale(.98)'},{opacity:1,transform:'none'}],{duration:340,easing:'cubic-bezier(.2,.8,.2,1)'}))};
// Pointer-based drag avoids a native drag image and supports touch handles.
let suppressClick=false;
$('#file-list').addEventListener('click',e=>{if(suppressClick){e.preventDefault();e.stopImmediatePropagation();suppressClick=false}},true);
$('#file-list').addEventListener('pointerdown',e=>{const row=e.target.closest('[data-file]');if(!row||e.button!==0||e.target.closest('.keep'))return;if(e.pointerType==='touch'&&!e.target.closest('.file-grab'))return;const id=+row.dataset.file,startX=e.clientX,startY=e.clientY;let ghost=null,active=false,over=false;row.setPointerCapture(e.pointerId);const move=ev=>{if(!active&&Math.hypot(ev.clientX-startX,ev.clientY-startY)>6){active=true;row.classList.add('drag-source');ghost=document.createElement('div');ghost.className='file-drag-ghost';ghost.innerHTML=icon(files.find(f=>f.id===id))+`<span>${files.find(f=>f.id===id).name}</span>`;document.body.append(ghost);switchTab('preview')}if(!active)return;ev.preventDefault();ghost.style.left=ev.clientX+'px';ghost.style.top=ev.clientY+'px';const r=$('.preview').getBoundingClientRect();over=ev.clientX>=r.left&&ev.clientX<=r.right&&ev.clientY>=r.top&&ev.clientY<=r.bottom;$('.preview').classList.toggle('drop-ready',over)};const finish=ev=>{row.removeEventListener('pointermove',move);row.removeEventListener('pointerup',finish);row.removeEventListener('pointercancel',cancel);row.classList.remove('drag-source');$('.preview').classList.remove('drop-ready');ghost?.remove();if(row.hasPointerCapture(e.pointerId))row.releasePointerCapture(e.pointerId);if(active){suppressClick=true;setTimeout(()=>suppressClick=false,100);if(over&&ev.type==='pointerup'){openDemoFile(id);toast('Added to the preview board. Drag its handle to rearrange.')}}};const cancel=ev=>{over=false;finish(ev)};row.addEventListener('pointermove',move);row.addEventListener('pointerup',finish);row.addEventListener('pointercancel',cancel)});
// Spring repulsion combines with a reversible, scroll-driven collection path.
const hero=$('.hero'),collector=$('.hero-collector'),heroFiles=$$('.hero-file');
let pointer={x:-10000,y:-10000},frame=0,lastTime=0,settle=0;
const particles=heroFiles.map(el=>({el,x:0,y:0,vx:0,vy:0}));
function animateHero(now){frame=0;const dt=Math.min((now-lastTime)/16.67||1,2);lastTime=now;const rect=hero.getBoundingClientRect(),progress=Math.max(0,Math.min(1,-rect.top/(rect.height*.54))),ease=progress*progress*(3-2*progress),targetX=collector.offsetLeft+collector.offsetWidth/2,targetY=collector.offsetTop+collector.offsetHeight/2;hero.style.setProperty('--gather',ease);let moving=false;
for(const p of particles){const x=p.el.offsetLeft+p.el.offsetWidth/2,y=p.el.offsetTop+p.el.offsetHeight/2,dx=x+rect.left-pointer.x,dy=y+rect.top-pointer.y,d=Math.hypot(dx,dy),force=d<180?(1-d/180)*78*(1-ease):0,rx=d?dx/d*force:0,ry=d?dy/d*force:0,tx=(targetX-x)*ease+rx,ty=(targetY-y)*ease+ry;p.vx=(p.vx+(tx-p.x)*.11*dt)*Math.pow(.72,dt);p.vy=(p.vy+(ty-p.y)*.11*dt)*Math.pow(.72,dt);p.x+=p.vx*dt;p.y+=p.vy*dt;if(Math.abs(p.vx)+Math.abs(p.vy)>.03||Math.abs(tx-p.x)+Math.abs(ty-p.y)>.2)moving=true;const angle=parseFloat(getComputedStyle(p.el).getPropertyValue('--tilt'));p.el.style.transform=`translate3d(${p.x}px,${p.y}px,0) rotate(${angle*(1-ease)}deg) scale(${1-ease*.83})`;p.el.style.opacity=1-Math.max(0,(ease-.75)/.25)}
if(moving||settle>0){settle--;frame=requestAnimationFrame(animateHero)}}
function wakeHero(){if(reduceMotion.matches){heroFiles.forEach(el=>{el.style.transform='';el.style.opacity=''});return}settle=8;if(!frame){lastTime=performance.now();frame=requestAnimationFrame(animateHero)}}
hero.addEventListener('pointermove',e=>{pointer={x:e.clientX,y:e.clientY};wakeHero()});hero.addEventListener('pointerleave',()=>{pointer={x:-10000,y:-10000};wakeHero()});addEventListener('scroll',wakeHero,{passive:true});addEventListener('resize',wakeHero);reduceMotion.addEventListener('change',()=>{if(frame)cancelAnimationFrame(frame);frame=0;wakeHero()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&frame){cancelAnimationFrame(frame);frame=0}else wakeHero()});render();renderPreviews();wakeHero();
